  (28, 16, 2, 5, 'memahami konsep dasar algoritma, sejarah dan perkembangan nya, serta perannya dalam pengembangan aplikasi modern', 'menyusun kode program dan membuat game sederhana dengan Block Code menggunakan aplikasi Scratch', 'bekerjasama dalam project team', '2025-06-28 15:37:11', '2025-06-28 15:37:11'),
