  (30, 13, 3, 1, 'menerapkan prinsip-prinsip Desain Grafis dalam karya visual', 'berkreasi menggunakan tools pada aplikasi Adobe Illustrator', 'berkreasi menggunakan tools pada aplikasi Inkscape', '2024-12-30 22:51:33', '2024-12-30 22:51:33'),
