  (35, 20, 3, 1, 'memahami penjelasan bahasa Arab yang didengar saat di kelas maupun dalam berkomunikasi', 'menggunakan Bahasa Arab dalam percakapan sehari-hari', 'memahami kaidah Bahasa Arab dalam Isim. Fiil, dan Harf', '2024-12-24 03:32:49', '2024-12-24 03:32:49'),
  (36, 19, 3, 6, 'memahami dan mengamalkan materi Adab kepada alloh, adab kepada nabi dan para rosul, adab terhdap al quran', 'memahami dan mengamalkan materi Adab terhadap teman, adab terhadap orang tua, adab terhadab saudara, adab terhadap tetangga.', 'memahami dan mengamalkan materi adab terhdap guru, adab di dalam masjid,abad di dalam rumah, adab di dalam masjid, adab terhdap saudara semuslim, adab terhadap orang kafir, memahami adab alwala wal baro', '2024-12-30 09:55:25', '2024-12-30 09:55:25'),
  (37, 21, 3, 6, 'memahami bab Thoharoh: tanda tanda baligh, syarat istinja dengan batu, fardhu wudhu, pengertian niat, syrat wudhu, pembatal wudhu, perkara yg haram di lakukan bagi yg tidak punya wudhu.', 'memahami bab Thoharoh: sebab tayamum, syarat tayamum, fardhu tayamum, perkara yg membatalkan tayamum, perkara yg mewajibkan mandi, fardhu mandi wajib, pembagian dan jenis jenis air, perkara najis yg bisa suci, pembagian najis, cara mensucikan najis.', 'Memahami bab Haid; waktu waktu haid, cara menghitung masa haid, mengetahui darah haid, nifas, dan istihadoh. Bab Sholat: syarat sah solat, rukun sholat, adab sholat.', '2024-12-30 09:45:36', '2024-12-30 09:45:36'),
  (38, 22, 3, 6, 'mengenal rukun iman dan rukun islam, memahami dari rukun iman dan rukun islam, Hifdzul Mutun Utsulu Tsalatsah', 'mengenal dan memahami Iman kepada Allah dari segi rububiyah, uluhiyyah, dan asma wasyifat. Hifdzul Mutun Utsulu Tsalatsah', 'memahami ma''rifatu Rasul: mengenal rosul dari segi adab dan meyakini seluruh risalah yg di bawanya.', '2024-12-30 09:48:17', '2024-12-30 09:48:17'),
  (39, 21, 1, 6, 'memahami makna lailahailloh,tanda tanda baligh,syarat istinja menggunakan batu dan tingkatan istinja.', 'memahami materi kewajiban wudhu dan rukun rukun nya ,pengertian niat,jenis jenis dan macam macam air,syarat wudhu,pembatal pembatal wudhu.', 'memahami Orang yg tidak punya wudhu,junub,dan haid.siapa saja yg wajib mandi besar,rukun mandi.asbab tayammum,syarat tayamum,furud tayamum,pembatal tayamum,segala sesuatu yg najis bisa menjadi suci.', '2025-06-26 14:19:02', '2025-06-26 14:19:02'),
  (41, 2, 3, 4, 'disiplin tepat waktu mengikuti halaqah Tahfidz', 'menjaga ketertiban dan kebersihan saat halaqah', 'taat duduk rapi terjaga dari kantuk saat halaqah berlangsung hingga akhir', '2025-01-02 00:15:09', '2025-01-02 00:15:09'),
