  (44, 5, 3, 4, 'menyetorkan hafalan sesuai target yang telah ditentukan', 'konsisten menyetorkan hafalan seauai target pada setiap tatap muka', 'mencapai target Tahfidz semesteran', '2025-01-02 00:14:04', '2025-01-02 00:14:04'),
  (46, 6, 1, 3, 'memahami materi yang didengarkan dan yang disampaikan oleh guru', 'menyampaikan pemahaman nya di depan public secara offline dan online', 'mengaplikasikan apa yang disampaikan ke diri sendiri dan dipraktikan dalam keseharian dari hal yang kecil', '2024-12-30 12:25:01', '2024-12-30 12:25:01'),
  (47, 19, 1, 6, 'Memahami Dan Mengamalkan Bab Adab Menuntut Ilmu, Terhadap Guru, Dan Di Dalam Majlis', 'Memahami Dan Mengamalkan Bab Adab Di Dalam rumah, Di Dalam Masjid, Di Dalam WC, Adab Makan', 'Memahami Dan Mengamalkan Bab Adab Terhadap Orang Tua, Terhadap Saudara Kandung, Terhadap Muslim', '2025-01-01 13:42:17', '2025-01-01 13:42:17'),
  (48, 2, 4, 4, 'disiplin tepat waktu mengikuti halaqah Tahfidz.', 'menghormati dan mengikuti semua intruksi dari Ustadz/ah.', NULL, '2025-06-25 11:28:47', '2025-06-25 11:28:47'),
  (49, 2, 2, 4, 'disiplin tepat waktu mengikuti halaqah Tahfidz', 'menghormati dan mengikuti semua intruksi dari Ustadz/ah', NULL, '2025-06-25 11:28:25', '2025-06-25 11:28:25'),
  (51, 3, 4, 4, 'konsisten membaca dengan tartil ketika ziyadah hafalan baru.', 'konsisten membaca dengan tartil ketika Tatsbit penguatan hafalan baru.', 'konsisten membaca dengan tartil ketika muraja''ah hafalan.', '2025-06-25 11:39:18', '2025-06-25 11:39:18'),
  (52, 3, 2, 4, 'konsisten membaca dengan tartil ketika ziyadah hafalan baru.', 'konsisten membaca dengan tartil ketika tatsbit penguatan hafalan baru.', 'konsisten membaca dengan tartil ketika muraja''ah hafalan.', '2025-06-25 11:42:10', '2025-06-25 11:42:10'),
  (53, 4, 4, 4, 'menyetorkan hafalan tuhfah terhindar dari batas kesalahan yang telah ditentukan.', 'memahami hukum-hukum ilmu tajwid dengan baik.', 'konsisten mengamalkan hukum-hukum tajwid dalam setiap bacaan.', '2025-06-25 12:00:58', '2025-06-25 12:00:58'),
  (54, 4, 2, 4, 'memahami cara baca dengan baik dari setiap makhorijul huruf dan sifatnya.', 'konsisten dalam pengamalan dalam setiap bacaan.', NULL, '2025-06-25 16:31:26', '2025-06-25 16:31:26'),
  (55, 6, 4, 3, 'menyimak materi dengan baik, mengikuti arahan guru', 'menyampaikan pemahaman nya di depan public secara offline dan online dengan percaya diri', NULL, '2025-06-26 14:45:26', '2025-06-26 14:45:26'),
  (56, 7, 4, 3, 'bersikap baik, sopan, dan menerima nasehat,', 'mentaati peraturan dan perintah guru', 'Mengerjakan tuas dengan baik dan tuntas, dan belajar tepat waktu dan gesit', '2025-06-26 13:44:58', '2025-06-26 13:44:58'),
  (57, 22, 4, 1, 'memahami Al-Wala'' dan bersikap loyal terhadap islam dan muslimin, serta Al-Baro'' berlepas diri dan membenci kekafiran', 'menujukan sikap loyal terhadap ajaran islam dan dukungan terhadap saudara muslimin di Gaza dan negara yang dijajah. dengan Speakup dan menentang segala bentuk penjajahan dan kedzoliman', NULL, '2025-06-26 13:56:04', '2025-06-26 13:56:04'),
  (58, 21, 4, 1, 'memahami urgensi ilmu dalam pengamalan Fiqih Ibadah, memahami asal hukum ibadah adalah haram kecuali ada dalil yang mewajibkan dan mensunnahkan', 'memanfaatkan teknologi dalam riset ilmiyah, memahami prinsip-prinsip yang harus dipegang dalam pengambilan referensi dan sumber tambahan', NULL, '2025-06-26 14:15:58', '2025-06-26 14:15:58'),
  (59, 21, 2, 1, 'memahami pentingnya ilmu dalam pengamalan Fiqih Ibadah, memahami asal hukum ibadah adalah haram kecuali ada dalil yang mewajibkan dan mensunnahkan', 'mengenal pemanfaatan teknologi dalam riset ilmiyah, memahami prinsip-prinsip yang harus dipegang dalam pengambilan referensi dan sumber tambahan', NULL, '2025-06-26 14:21:12', '2025-06-26 14:21:12'),
  (60, 19, 2, 1, 'memahami adab dalam merawat niat, adab kepada Allah dan Rasul-Nya, adab dalam belajar, mengamalkan ilmu serta menyebarkan nya', 'memahami adab dalam berinteraksi di media sosial, batasan membuat konten yang dibolehkan dan diperlukan.', NULL, '2025-06-28 08:44:56', '2025-06-28 08:44:56'),
  (61, 16, 4, 5, 'berkreasi dalam membuat animasi, aplikasi dan game edukatif', 'mengembangkan kemampuan coding dengan Scratch dalam membuat game yang lebih kompleks', 'berkolaborasi dengan tim dalam project pengembangan aplikasi game', '2025-06-27 23:47:46', '2025-06-27 23:47:46'),
  (62, 23, 4, 1, 'memahami Algoritma dan jenis-jenis nya dalam bahasa pemrograman Python', 'berkreasi dalam membuat aplikasi CLI dan GUI desktop sederhana menggunakan Python', 'bekerja menggunakan AI dalam membuat aplikasi, serta berusaha memahami setiap baris kode yang disarankan', '2025-06-26 15:01:18', '2025-06-26 15:01:18'),
  (63, 23, 2, 1, 'memahami Algoritma dan jenis-jenis nya dalam bahasa pemrograman Python', 'berkreasi dalam membuat aplikasi CLI dan GUI desktop sederhana menggunakan Python', NULL, '2025-06-26 15:07:37', '2025-06-26 15:07:37'),
  (64, 9, 4, 2, 'menangkap inti dan detail informasi dari berbagai teks berbahasa Inggris. menyimpulkan makna dan memahami ide-ide yang tersirat dalam bacaan.', 'menggunakan struktur kalimat dan kaidah tata bahasa yang benar dalam berkomunikasi. memiliki kosa kata yang cukup untuk mengungkapkan pikiran secara efektif dan akurat.', 'menyusun tulisan yang koheren dan logis. mengembangkan ide dan argumen secara terstruktur dalam bentuk tulisan.', '2025-06-26 15:42:34', '2025-06-26 15:42:34'),
  (65, 9, 2, 2, 'Memahami informasi penting dari teks berbahasa Inggris sederhana.', 'Menggunakan tata bahasa dasar dan kosakata umum dalam percakapan dan tulisan.', 'Menulis kalimat dan paragraf sederhana dalam bahasa Inggris.', '2025-06-26 15:43:25', '2025-06-26 15:43:25'),
  (68, 5, 4, 4, 'disiplin ziyadah hafalan baru tepat waktu.', 'menyetorkan sesuai target yang telah ditentukan.', 'konsisten menambah hafalan setiap harinya.', '2025-06-29 22:56:12', '2025-06-29 22:56:12'),
  (69, 5, 2, 4, 'disiplin ziyadah hafalan baru tepat waktu.', 'menyetorkan hafalan sesuai target yang telah ditentukan.', 'konsisten menyetorkan hafalan setiap harinya.', '2025-06-29 23:11:45', '2025-06-29 23:11:45'),
  (70, 8, 2, 4, 'mengidentifikasi dan memahami arti kosa kata baru.', 'memahami konsep mudzakkar (laki-laki) dan muannats (perempuan) pada kata benda dan kata sifat.', 'menggunakan kosa kata tersebut dalam konteks kalimat sederhana secara lisan maupun tulisan.', '2025-06-29 23:12:18', '2025-06-29 23:12:18'),
  (71, 8, 4, 4, 'mengidentifikasi dan memahami arti kosa kata baru.', 'memahami inti percakapan sederhana yang berkaitan dengan topik.', 'menjawab pertanyaan berdasarkan teks yang telah dibaca.', '2025-06-29 23:12:40', '2025-06-29 23:12:40')
