  (14, 3846622, 4, 1, 2, NULL, 65, 65, 70, 70, 79, 79, TRUE, 'dan mulai terbiasa membuka mulut, Reflex mengucapkan huruf ke huruf, Namun masih ada beberapa huruf yg nasih tertukar seperti huruf "za" dan "ra"', FALSE, NULL, FALSE, NULL, '2024-02-28 05:51:26', '2024-02-28 05:56:00'),
