  "competence_3" = EXCLUDED."competence_3",
  "created_at" = EXCLUDED."created_at",
  "updated_at" = EXCLUDED."updated_at";

SELECT setval(pg_get_serial_sequence('"academy_competences"', 'id'), coalesce(max(id), 1)) FROM "academy_competences";

